$ComposeFile = "infra/docker/compose.runtime.yml"; $EnvFile = "infra/docker/env/runtime.env.example"; $MigrationDir = "services/wlt/database/migrations"; $MigrationFiles = @(Get-ChildItem -LiteralPath $MigrationDir -Filter "*.sql"); foreach ($file in $MigrationFiles) { $checksum = (Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash.ToLowerInvariant(); $sql = "UPDATE runtime_schema_migrations SET checksum = '$checksum' WHERE migration_name = '$($file.Name)';"; docker compose --env-file $EnvFile -f $ComposeFile exec -T postgres psql -U wlt_runtime -d wlt_runtime -c $sql; Write-Host "Updated $($file.Name) to $checksum" }
